dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "phenotype",
      "label": "Phenotype*",
      "type": "api list",
      "data point": {
        "type": "api",
        "url": "https://igvf.hugeampkpnbi.org/lipids/api/bio/keys/global-associations/2?columns=phenotype",
        "data type": "json",
        "data wrapper": [
          "keys"
        ]
      }
    },
    {
      "parameter": "ancestry",
      "label": "Ancestry*",
      "type": "list",
      "values": [
        {
          "label": "Mixed",
          "value": "*"
        },
        {
          "label": "AF",
          "value": "AF"
        },
        {
          "label": "EA",
          "value": "EA"
        },
        {
          "label": "EU",
          "value": "EU"
        },
        {
          "label": "HS",
          "value": "HS"
        },
        {
          "label": "SA",
          "value": "SA"
        }
      ]
    },
    {
      "parameter": "region",
      "label": "Set region (PCSK9,chr:start-end)",
      "type": "input",
      "values": "kp genes",
      "convert to region": "true",
      "expand region by": 100000
    },
    {
      "parameter": "tissue",
      "label": "Tissue",
      "type": "input",
      "display": "false",
      "note": "this one is for indexes that take underscored tissue names"
    },
    {
      "parameter": "tissueSpaced",
      "label": "Tissue",
      "type": "input",
      "display": "false",
      "note": "this one is for indexes that take spaced tissue names"
    },
    {
      "parameter": "clump",
      "label": "clump",
      "type": "input",
      "display": "false"
    },
    {
      "parameter": "csid",
      "label": "CS ID",
      "type": "input",
      "display": "false"
    }
  ],
  "tab groups": [
    {
      "label": "Phenotype Associations",
      "sections": [
        {
          "section": "associations",
          "label": "Associated variants in region"
        },
        {
          "section": "c2ct",
          "label": "CS2CT"
        },
        {
          "section": "global_associations",
          "label": "Genome-wide associations"
        },
        {
          "section": "gene_finder",
          "label": "Associated genes"
        }
      ]
    },
    {
      "label": "credible sets",
      "sections": [
        {
          "section": "credible_sets",
          "label": "Credible sets in region"
        }
      ]
    },
    {
      "label": "credible variants",
      "sections": [
        {
          "section": "credible_variants",
          "label": "Variants in credible set"
        }
      ]
    },
    {
      "label": "Tissue / Annotation",
      "sections": [
        {
          "section": "partitioned_heritability",
          "label": "Partitioned Heritability"
        },
        {
          "section": "global_enrichment",
          "label": "Globally Enriched Tissues / Annotations"
        },
        {
          "section": "regions",
          "label": "Tissue-level annotations"
        },
        {
          "section": "tissue_regions",
          "label": "Biosample-level annotations"
        }
      ]
    },
    {
      "label": "Gene Links",
      "sections": [
        {
          "section": "gene_links",
          "label": "Target gene links"
        },
        {
          "section": "variant_links",
          "label": "SNP to Gene Links"
        }
      ]
    },
    {
      "label": "Summary",
      "type": "fixed bottom",
      "sections": [
        {
          "section": "page_summary",
          "label": "Page Summary"
        }
      ]
    }
  ],
  "sections": [
    {
      "section id": "credible_sets",
      "header": "Credible Sets",
      "data point": {
        "type": "bioindex",
        "url": "https://igvf.hugeampkpnbi.org/lipids/api/bio/",
        "index": "credible-sets",
        "parameters": [
          "phenotype",
          "ancestry",
          "region"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "CS ID",
            "raw field": "credibleSetId"
          },
          {
            "type": "join multi",
            "field name": "CS region",
            "fields to join": [
              "chromosome",
              "start",
              "end"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "calculate",
            "calculation type": "math",
            "field name": "region length",
            "expression": [
              "end",
              "-",
              "start"
            ],
            "note": "required to get clumped region center"
          },
          {
            "type": "join multi",
            "field name": "CS region (length)",
            "fields to join": [
              "CS region",
              "region length"
            ],
            "join by": [
              " (",
              "bp)"
            ]
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "Method",
            "raw field": "method"
          },
          {
            "type": "raw",
            "field name": "PMID",
            "raw field": "pmid"
          }
        ],
        "top rows": [
          "CS ID",
          "CS region (length)",
          "Dataset",
          "Method",
          "PMID"
        ],
        "column formatting": {
          "CS ID": {
            "type": [
              "set parameter"
            ],
            "target sections": [
              {
                "section": "all",
                "label": "Load variants to CS variants table",
                "parameter": [
                  "csid"
                ]
              }
            ]
          }
        }
      },
      "filters": [
        {
          "field": "Dataset",
          "label": "Dataset",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "Method",
          "label": "Method",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "PMID",
          "label": "PMID",
          "type": "checkbox",
          "label in bubble": "true"
        }
      ]
    },
    {
      "section id": "credible_variants",
      "header": "Credible Variants",
      "data point": {
        "type": "bioindex",
        "url": "https://igvf.hugeampkpnbi.org/lipids/api/bio/",
        "index": "credible-variants",
        "parameters": [
          "phenotype",
          "ancestry",
          "csid"
        ],
        "cumulate data": "false",
        "parameters type": "array",
        "data type": "bioindex",
        "region": "region"
      },
      "table format": {
        "data convert": [
          {
            "type": "join multi",
            "field name": "Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              "_",
              "/"
            ]
          },
          {
            "type": "join multi",
            "field name": "Open V2F page",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              ":",
              ":"
            ]
          },
          {
            "type": "raw",
            "field name": "CV Variant ID",
            "raw field": "Variant ID"
          },
          {
            "type": "join multi",
            "field name": "Ref/Alt",
            "fields to join": [
              "reference",
              "alt"
            ],
            "join by": [
              "/"
            ]
          },
          {
            "type": "raw",
            "field name": "PPO",
            "raw field": "posteriorProbability"
          },
          {
            "type": "raw",
            "field name": "CS ID",
            "raw field": "credibleSetId"
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "Method",
            "raw field": "method"
          },
          {
            "type": "raw",
            "field name": "EAF",
            "raw field": "eaf"
          },
          {
            "type": "raw",
            "field name": "PMID",
            "raw field": "pmid"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "position"
          }
        ],
        "top rows": [
          "Variant ID",
          "Open V2F page",
          "PPO",
          "CS ID",
          "Dataset",
          "EAF",
          "Method",
          "Position",
          "PMID"
        ],
        "locus field": "CS region",
        "star column": "Variant ID",
        "column formatting": {
          "Open V2F page": {
            "type": [
              "link"
            ],
            "link to": "/research.html?pageid=igvf_lipids_variant&variant=",
            "link type": "button",
            "link label": "Open",
            "new tab": "true"
          },
          "Get V2F scores": {
            "label": "Set variant",
            "type": [
              "set parameter"
            ],
            "target sections": [
              {
                "section": "all",
                "label": "Load V2F scores",
                "parameter": [
                  "variant"
                ]
              }
            ]
          },
          "PPO": {
            "type": [
              "scientific notation"
            ]
          }
        }
      },
      "filters": [
        {
          "field": "PPO",
          "label": "PPO(>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "EAF",
          "label": "EAF(>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Dataset",
          "label": "Dataset",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "Method",
          "label": "Method",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "PMID",
          "label": "PMID",
          "type": "checkbox",
          "label in bubble": "true"
        }
      ]
    },
    {
      "section id": "c2ct",
      "header": "CS2CT",
      "data point": {
        "type": "bioindex",
        "url": "https://igvf.hugeampkpnbi.org/lipids/api/bio/query/c2ct?q=$phenotype",
        "continue url": "https://igvf.hugeampkpnbi.org/lipids/api/bio/cont?limit=20000&token=",
        "parameters": [
          "phenotype"
        ],
        "parameters type": "replace",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Annotation",
            "raw field": "annotation",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Biosample",
            "raw field": "biosample"
          },
          {
            "type": "raw",
            "field name": "Source",
            "raw field": "source"
          },
          {
            "type": "raw",
            "field name": "CS ID",
            "raw field": "credibleSetId"
          },
          {
            "type": "raw",
            "field name": "chromosome",
            "raw field": "chromosome"
          },
          {
            "type": "calculate",
            "calculation type": "math",
            "field name": "region length",
            "expression": [
              "clumpEnd",
              "-",
              "clumpStart"
            ],
            "note": "required to get clumped region center"
          },
          {
            "type": "join multi",
            "field name": "CS region (length)",
            "fields to join": [
              "chromosome",
              "clumpStart",
              "clumpEnd",
              "region length"
            ],
            "join by": [
              ":",
              "-",
              " (",
              "bp)"
            ]
          },
          {
            "type": "join multi",
            "field name": "CS region",
            "fields to join": [
              "chromosome",
              "clumpStart",
              "clumpEnd"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "split",
            "field name": [
              "lead chr",
              "position ref alt"
            ],
            "field to split": "leadSNP",
            "split by": [
              ":"
            ]
          },
          {
            "type": "split",
            "field name": [
              "Lead SNP position",
              "ref alt"
            ],
            "field to split": "position ref alt",
            "split by": [
              ":"
            ]
          },
          {
            "type": "split",
            "field name": [
              "lead ref",
              "lead alt"
            ],
            "field to split": "ref alt",
            "split by": [
              ":"
            ]
          },
          {
            "type": "join multi",
            "field name": "Lead SNP",
            "fields to join": [
              "lead chr",
              "Lead SNP position",
              "lead ref",
              "lead alt"
            ],
            "join by": [
              ":",
              "_",
              "/"
            ]
          },
          {
            "type": "raw",
            "field name": "Variant ID",
            "raw field": "Lead SNP"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "Lead SNP position"
          },
          {
            "type": "calculate",
            "calculation type": "math",
            "field name": "regionStart",
            "expression": [
              "Lead SNP position",
              "-",
              200000
            ],
            "note": ""
          },
          {
            "type": "calculate",
            "calculation type": "math",
            "field name": "regionEnd",
            "expression": [
              "Lead SNP position",
              "+",
              200000
            ],
            "note": ""
          },
          {
            "type": "join multi",
            "field name": "View variants in CS & Lead SNP +-200kb",
            "fields to join": [
              "CS ID",
              "chromosome",
              "regionStart",
              "regionEnd"
            ],
            "join by": [
              ",",
              ":",
              "-"
            ]
          },
          {
            "type": "join multi",
            "field name": "Load annotation + tissue + biosample CS2CT",
            "fields to join": [
              "annotation",
              "tissue",
              "biosample"
            ],
            "join by": [
              ",",
              ","
            ]
          },
          {
            "type": "raw",
            "field name": "PPO",
            "raw field": "posteriorProbability",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "Total entropy",
            "raw field": "totalEntropy",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "Entropy",
            "raw field": "entropy",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "Entropy in",
            "raw field": "entropy_in",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Entropy out",
            "raw field": "entropy_out",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Q",
            "raw field": "Q",
            "if no value": 0
          },
          {
            "type": "join multi",
            "field name": "Biosample:CS region",
            "fields to join": [
              "Biosample",
              "CS region"
            ],
            "join by": [
              ":"
            ]
          },
          {
            "type": "raw",
            "field name": "Annotation bp",
            "raw field": "annot_bp",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Entropy PP",
            "raw field": "entPP",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Entropy type",
            "raw field": "entropyType",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Lead SNP p-value",
            "raw field": "leadSNPPValue",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Overlap lead SNP",
            "raw field": "overlapLeadSNP",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Number of overlapping SNPs in CS",
            "raw field": "varOverlap",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Number of SNPs in CS",
            "raw field": "varTotal",
            "if no value": "N/A"
          }
        ],
        "top rows": [
          "Annotation",
          "Tissue",
          "Biosample",
          "Source",
          "Number of SNPs in CS",
          "Lead SNP",
          "Lead SNP p-value",
          "PPO",
          "Entropy",
          "Entropy in",
          "Entropy out",
          "View variants in CS & Lead SNP +-200kb"
        ],
        "star column": "Variant ID",
        "column formatting": {
          "Load annotation + tissue + biosample CS2CT": {
            "type": [
              "set parameter"
            ],
            "label": "Load data",
            "target sections": [
              {
                "section": "all",
                "label": "Set annotation, tissue & biosample",
                "parameter": [
                  "annotation",
                  "tissue",
                  "biosample"
                ]
              }
            ]
          },
          "CS ID": {
            "type": [
              "shorten"
            ],
            "shorten to": 10,
            "shorten anchor": "end"
          },
          "PPO": {
            "type": [
              "scientific notation"
            ]
          },
          "Entropy": {
            "type": [
              "scientific notation"
            ]
          },
          "Total entropy": {
            "type": [
              "scientific notation"
            ]
          },
          "Q": {
            "type": [
              "scientific notation"
            ]
          },
          "View variants in CS & Lead SNP +-200kb": {
            "type": [
              "set parameter"
            ],
            "label": "Load variants",
            "target sections": [
              {
                "section": "all",
                "label": "Set CS ID & Region",
                "parameter": [
                  "csid",
                  "region"
                ]
              }
            ]
          }
        },
        "features": [
          "Anno",
          "Var",
          "Ent"
        ],
        "features header": "More info",
        "Anno": [
          "Annotation",
          "Annotation bp"
        ],
        "Var": [
          "Lead SNP",
          "Lead SNP p-value",
          "Overlap lead SNP",
          "Number of overlapping SNPs in CS",
          "Number of SNPs in CS"
        ],
        "Ent": [
          "Entropy",
          "Entropy in",
          "Entropy out",
          "Entropy PP",
          "Entropy type",
          "Total entropy"
        ]
      },
      "filters": [
        {
          "field": "Annotation",
          "label": "Annotation",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "Tissue",
          "label": "Tissue",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "chromosome",
          "label": "Chromosome",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "CS ID",
          "label": "CS ID",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "Source",
          "label": "Source",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "PPO",
          "label": "PPO(>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Lead SNP p-value",
          "label": "Lead SNP p-value(<=)",
          "type": "search lower than",
          "label in bubble": "true"
        },
        {
          "field": "Entropy",
          "label": "Entropy(<=)",
          "type": "search lower than",
          "label in bubble": "true"
        }
      ],
      "visualizers": {
        "wrapper type": "tabs",
        "visualizers": [
          {
            "label": "PPO vs Entropy",
            "type": "scatter plot",
            "star key": "Biosample:CS region",
            "render type": "single plot",
            "group by": "Phenotype",
            "color by": "Source",
            "x axis field": "Entropy",
            "x axis label": "Entropy",
            "y axis field": "PPO",
            "y axis label": "PPO",
            "ticks decimal point": "4",
            "render by": "Biosample:CS region",
            "hover content": [
              "PPO",
              "Entropy",
              "Total entropy"
            ],
            "height": 150,
            "width": 450,
            "plot margin": {
              "left": 60,
              "right": 20,
              "top": 40,
              "bottom": 50,
              "bump": 5
            }
          },
          {
            "label": "PPO vs Entropy in (N/A)",
            "type": "scatter plot",
            "star key": "Biosample:CS region",
            "render type": "single plot",
            "group by": "Phenotype",
            "color by": "Source",
            "x axis field": "Entropy in",
            "x axis label": "Entropy in",
            "y axis field": "PPO",
            "y axis label": "PPO",
            "ticks decimal point": "4",
            "render by": "Biosample:CS region",
            "hover content": [
              "PPO",
              "Entropy in",
              "Total entropy"
            ],
            "height": 150,
            "width": 450,
            "plot margin": {
              "left": 60,
              "right": 20,
              "top": 40,
              "bottom": 50,
              "bump": 5
            }
          },
          {
            "label": "PPO vs Entropy out (N/A)",
            "type": "scatter plot",
            "star key": "Biosample:CS region",
            "render type": "single plot",
            "group by": "Phenotype",
            "color by": "Source",
            "x axis field": "Entropy out",
            "x axis label": "Entropy out",
            "y axis field": "PPO",
            "y axis label": "PPO",
            "ticks decimal point": "4",
            "render by": "Biosample:CS region",
            "hover content": [
              "PPO",
              "Entropy out",
              "Total entropy"
            ],
            "height": 150,
            "width": 450,
            "plot margin": {
              "left": 60,
              "right": 20,
              "top": 40,
              "bottom": 50,
              "bump": 5
            }
          }
        ]
      }
    },
    {
      "section id": "gene_finder",
      "header": "Gene Finder",
      "data point": {
        "type": "bioindex",
        "url": "https://igvf.hugeampkpnbi.org/lipids/api/bio/",
        "index": "gene-finder",
        "parameters": [
          "phenotype",
          "ancestry"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "initial sort by": {
          "field": "P-Value",
          "type": "number",
          "direction": "desc"
        },
        "data convert": [
          {
            "type": "raw",
            "field name": "Gene",
            "raw field": "gene"
          },
          {
            "type": "join multi",
            "field name": "Region",
            "fields to join": [
              "chromosome",
              "start",
              "end"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "calculate",
            "field name": "Start",
            "expression": [
              "start",
              "-",
              50000
            ],
            "calculation type": "math"
          },
          {
            "type": "calculate",
            "field name": "End",
            "expression": [
              "end",
              "+",
              50000
            ],
            "calculation type": "math"
          },
          {
            "type": "join multi",
